window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d2a6cfecbf247146"]={"versions": [{"id": "FIG-d2a6cfecbf247146", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / ParamDef) für den Ethernet Switch Driver (<code>EthSwt</code>). Das Diagramm spezifiziert die Konfigurationsparameter für Ports eines Ethernet-Switches hinsichtlich physikalischer Schnittstelle, MAC-Schnittstellentyp, Subtyp und Übertragungsgeschwindigkeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>EthSwtConfig</code></strong> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..*</code>): Übergeordneter Konfigurationscontainer.\n</li><li><strong><code>EthSwtPort</code></strong> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..*</code>): Per <code>+subContainer</code> in <code>EthSwtConfig</code> eingebetteter Container zur Parametrierung einzelner Switch-Ports.\n</li><li><strong><code>EthSwtPortPhysicalLayerType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den physikalischen Schnittstellentyp mit den Literalen (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>):\n<ul class=\"fig-list\"><li><code>ETHSWT_PORT_100BASE_TX</code>\n</li><li><code>ETHSWT_PORT_1000BASE_T</code>\n</li><li><code>ETHSWT_PORT_100BASE_T1</code>\n</li><li><code>ETHSWT_PORT_1000BASE_T1</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den MAC-Schnittstellentyp mit den Literalen:\n<ul class=\"fig-list\"><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XMII</code>\n</li><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XGMII</code>\n</li><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XXGMII</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerSubType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den Subtyp des MII-Interfaces mit den Literalen:\n<ul class=\"fig-list\"><li><code>STANDARD</code>\n</li><li><code>REDUCED</code>\n</li><li><code>REVERSED</code>\n</li><li><code>SERIAL</code>\n</li><li><code>UNIVERSAL_SERIAL</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerSpeed</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für die Portgeschwindigkeit mit den Literalen:\n<ul class=\"fig-list\"><li><code>ETH_MAC_LAYER_SPEED_10M</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_100M</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_1G</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_10G</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_2500M</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell- und Parameterspezifikation; es wird kein dynamisches Laufzeitverhalten oder Protokollablauf dargestellt. Die Parameter steuern die statische Generierung und Initialisierung der Switch-Port-Hardware bzw. Port-Treiberinstanzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-Konfigurationsparameter (ECUC-Definition) für Switch-Ports. Alle vier Enumerationsparameter besitzen die Multiplizität <code>0..1</code> und sind somit optional je Port konfigurierbar. Konfiguratoren und Codegeneratoren müssen die definierten Literale validieren und zur statischen Konfiguration der Port-Register bzw. Hardwaretreiber des Ethernet-Switches verwenden.</p>"}, {"id": "FIG-8e043815952a197e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / ParamDef) für den Ethernet Switch Driver (<code>EthSwt</code>). Das Diagramm spezifiziert die Konfigurationsparameter für Ports eines Ethernet-Switches hinsichtlich physikalischer Schnittstelle, MAC-Schnittstellentyp, Subtyp und Übertragungsgeschwindigkeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>EthSwtConfig</code></strong> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..*</code>): Übergeordneter Konfigurationscontainer.\n</li><li><strong><code>EthSwtPort</code></strong> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..*</code>): Per <code>+subContainer</code> in <code>EthSwtConfig</code> eingebetteter Container zur Parametrierung einzelner Switch-Ports.\n</li><li><strong><code>EthSwtPortPhysicalLayerType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den physikalischen Schnittstellentyp mit den Literalen (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>):\n<ul class=\"fig-list\"><li><code>ETHSWT_PORT_100BASE_TX</code>\n</li><li><code>ETHSWT_PORT_1000BASE_T</code>\n</li><li><code>ETHSWT_PORT_100BASE_T1</code>\n</li><li><code>ETHSWT_PORT_1000BASE_T1</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den MAC-Schnittstellentyp mit den Literalen:\n<ul class=\"fig-list\"><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XMII</code>\n</li><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XGMII</code>\n</li><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XXGMII</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerSubType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den Subtyp des MII-Interfaces mit den Literalen:\n<ul class=\"fig-list\"><li><code>STANDARD</code>\n</li><li><code>REDUCED</code>\n</li><li><code>REVERSED</code>\n</li><li><code>SERIAL</code>\n</li><li><code>UNIVERSAL_SERIAL</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerSpeed</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für die Portgeschwindigkeit mit den Literalen:\n<ul class=\"fig-list\"><li><code>ETH_MAC_LAYER_SPEED_10M</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_100M</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_1G</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_10G</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_2500M</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell- und Parameterspezifikation; es wird kein dynamisches Laufzeitverhalten oder Protokollablauf dargestellt. Die Parameter steuern die statische Generierung und Initialisierung der Switch-Port-Hardware bzw. Port-Treiberinstanzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-Konfigurationsparameter (ECUC-Definition) für Switch-Ports. Alle vier Enumerationsparameter besitzen die Multiplizität <code>0..1</code> und sind somit optional je Port konfigurierbar. Konfiguratoren und Codegeneratoren müssen die definierten Literale validieren und zur statischen Konfiguration der Port-Register bzw. Hardwaretreiber des Ethernet-Switches verwenden.</p>"}, {"id": "FIG-7d0c1a32fe0d82b2", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / ParamDef) für den Ethernet Switch Driver (<code>EthSwt</code>). Das Diagramm spezifiziert die Konfigurationsparameter für Ports eines Ethernet-Switches hinsichtlich physikalischer Schnittstelle, MAC-Schnittstellentyp, Subtyp und Übertragungsgeschwindigkeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>EthSwtConfig</code></strong> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..*</code>): Übergeordneter Konfigurationscontainer.\n</li><li><strong><code>EthSwtPort</code></strong> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..*</code>): Per <code>+subContainer</code> in <code>EthSwtConfig</code> eingebetteter Container zur Parametrierung einzelner Switch-Ports.\n</li><li><strong><code>EthSwtPortPhysicalLayerType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den physikalischen Schnittstellentyp mit den Literalen (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>):\n<ul class=\"fig-list\"><li><code>ETHSWT_PORT_10BASE_T1S</code>\n</li><li><code>ETHSWT_PORT_100BASE_TX</code>\n</li><li><code>ETHSWT_PORT_1000BASE_T</code>\n</li><li><code>ETHSWT_PORT_100BASE_T1</code>\n</li><li><code>ETHSWT_PORT_1000BASE_T1</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den MAC-Schnittstellentyp mit den Literalen:\n<ul class=\"fig-list\"><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XMII</code>\n</li><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XGMII</code>\n</li><li><code>ETHSWT_PORT_MAC_LAYER_TYPE_XXGMII</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerSubType</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für den Subtyp des MII-Interfaces mit den Literalen:\n<ul class=\"fig-list\"><li><code>STANDARD</code>\n</li><li><code>REDUCED</code>\n</li><li><code>REVERSED</code>\n</li><li><code>SERIAL</code>\n</li><li><code>UNIVERSAL_SERIAL</code>\n</li></ul>\n</li><li><strong><code>EthSwtPortMacLayerSpeed</code></strong> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>0..1</code> via <code>+parameter</code>): Aufzählungsparameter für die Portgeschwindigkeit mit den Literalen:\n<ul class=\"fig-list\"><li><code>ETH_MAC_LAYER_SPEED_10M</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_100M</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_1G</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_10G</code>\n</li><li><code>ETH_MAC_LAYER_SPEED_2500M</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell- und Parameterspezifikation; es wird kein dynamisches Laufzeitverhalten oder Protokollablauf dargestellt. Die Parameter steuern die statische Generierung und Initialisierung der Switch-Port-Hardware bzw. Port-Treiberinstanzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-Konfigurationsparameter (ECUC-Definition) für Switch-Ports. Alle vier Enumerationsparameter besitzen die Multiplizität <code>0..1</code> und sind somit optional je Port konfigurierbar. Konfiguratoren und Codegeneratoren müssen die definierten Literale – einschließlich 10BASE-T1S für automobile Single-Pair-Ethernet-Multidrop-/Punkt-zu-Punkt-Anbindungen – validieren und zur statischen Konfiguration der Port-Register bzw. Hardwaretreiber des Ethernet-Switches verwenden.</p>"}], "trans": [{"from": "FIG-d2a6cfecbf247146", "to": "FIG-8e043815952a197e", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8e043815952a197e", "to": "FIG-7d0c1a32fe0d82b2", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Aufzählungswert <code>ETHSWT_PORT_10BASE_T1S</code> (<code>EcucEnumerationLiteralDef</code>) zum Konfigurationsparameter <code>EthSwtPortPhysicalLayerType</code> ergänzt.\n</li></ul>"}]};
